import{_ as o,o as t,c as r,a5 as a}from"./chunks/framework.QWVCgkrI.js";const i="/study/images/os/io-completion-ports.svg",u=JSON.parse('{"title":"WindowsのI/O完了ポート（IOCP） — 要求の発行と完了の回収","description":"","frontmatter":{"title":"WindowsのI/O完了ポート（IOCP） — 要求の発行と完了の回収","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"複数のWindows非同期I/Oの完了を一つのポートで受け取る。完了キーとOVERLAPPEDの対応、即時成功でも通知が届く条件、失敗した完了の判定、ワーカーの並行度を説明する。","aliases":["I/O完了ポート","IOCP","I/O Completion Port","completion key","完了キー","CreateIoCompletionPort","GetQueuedCompletionStatus","PostQueuedCompletionStatus","FILE_SKIP_COMPLETION_PORT_ON_SUCCESS"],"verification":"MicrosoftのWin32 API仕様と解説に照合（2026-11-06）"}},"headers":[],"relativePath":"os/io-completion-ports.md","filePath":"os/io-completion-ports.md"}'),d={name:"os/io-completion-ports.md"};function n(s,e,c,l,p,f){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="windowsのi-o完了ポート-iocp-—-要求の発行と完了の回収" tabindex="-1">WindowsのI/O完了ポート（IOCP） — 要求の発行と完了の回収 <a class="header-anchor" href="#windowsのi-o完了ポート-iocp-—-要求の発行と完了の回収" aria-label="Permalink to &quot;WindowsのI/O完了ポート（IOCP） — 要求の発行と完了の回収&quot;">​</a></h1><p>Windowsの<strong>I/O完了ポート</strong>（IOCP）は、複数のハンドルで発行した非同期I/Oの結果を、一つのキューに集める仕組みです。例えば、二つのファイルから三つの読み取りを出すと、それぞれの完了を同じポートから回収できます。ワーカーはポートを待ち、取り出したパケットの値からファイルと要求を特定します。<a href="/study/os/asynchronous-file-io.html">非同期I/Oの基礎</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/fileio/i-o-completion-ports" target="_blank" rel="noreferrer">Microsoft: I/O Completion Ports</a></p><h2 id="ハンドルをポートに関連付ける" tabindex="-1">ハンドルをポートに関連付ける <a class="header-anchor" href="#ハンドルをポートに関連付ける" aria-label="Permalink to &quot;ハンドルをポートに関連付ける&quot;">​</a></h2><p>通常ファイルなら、まず<code>CreateFileW</code>で<code>FILE_FLAG_OVERLAPPED</code>を指定して開きます。読み取りを発行する前に、<code>CreateIoCompletionPort</code>でそのハンドルの完了通知の送り先を設定します。ポートを共有するファイルを後から追加する場合は、同じポートハンドルを渡します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-createiocompletionport" target="_blank" rel="noreferrer">Microsoft: CreateIoCompletionPort</a></p><table tabindex="0"><thead><tr><th><code>CreateIoCompletionPort</code>の呼び方</th><th>起きること</th></tr></thead><tbody><tr><td><code>CreateIoCompletionPort(INVALID_HANDLE_VALUE, nullptr, 0, concurrency)</code></td><td>ポートだけを作成する。完了キーの引数は無視される。</td></tr><tr><td><code>CreateIoCompletionPort(file, nullptr, key, concurrency)</code></td><td>ポートを作成し、<code>file</code>を関連付ける。</td></tr><tr><td><code>CreateIoCompletionPort(file, port, key, 0)</code></td><td><code>file</code>を既存ポートに関連付ける。成功時の戻り値は同じ<code>port</code>。並行度の引数は無視される。</td></tr></tbody></table><p>失敗時の戻り値は<code>nullptr</code>です。一つのハンドルが関連付くポートは一つで、関連付けはそのハンドルを閉じるまで続きます。同じ仕組みを、overlapped I/Oに対応するTCPソケットや名前付きパイプにも使えます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-createiocompletionport" target="_blank" rel="noreferrer">Microsoft: CreateIoCompletionPort</a></p><h2 id="完了キーでハンドルを、ポインターで要求を見分ける" tabindex="-1">完了キーでハンドルを、ポインターで要求を見分ける <a class="header-anchor" href="#完了キーでハンドルを、ポインターで要求を見分ける" aria-label="Permalink to &quot;完了キーでハンドルを、ポインターで要求を見分ける&quot;">​</a></h2><p>完了キー（<code>CompletionKey</code>）は関連付け時にアプリが渡す<code>ULONG_PTR</code>の値です。同じハンドルから生じたI/O完了パケットには同じキーが入ります。ハンドルごとの状態を区別したい場合は、アプリで別々のキーを割り当てます。<code>OVERLAPPED*</code>は<code>ReadFile</code>などに渡した構造体のアドレスです。一つのハンドルに複数の要求を出しても、要求ごとに異なる<code>OVERLAPPED</code>を渡せば、どの要求が完了したかを識別できます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-createiocompletionport" target="_blank" rel="noreferrer">Microsoft: CreateIoCompletionPort</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatus</a></p><figure class="study-figure"><img src="'+i+'" alt="キー10のファイルAに要求A1とA2、キー20のファイルBに要求B1を発行する。三つの完了が同じポートに入り、例ではA2、B1、A1の順に並ぶ。A1とA2のキーは同じ10で、OVERLAPPEDのアドレスは異なる。ワーカーはポートから結果を取り出す。" width="760" height="512" loading="lazy"><figcaption>完了した要求が一つのキューに集まります。各パケットの完了キーはハンドルとの対応、<code>OVERLAPPED*</code>は一回の読み取りとの対応を表します。<a href="/study/images/os/io-completion-ports.svg" target="_blank" rel="noopener noreferrer">完了通知の図を拡大</a></figcaption></figure><p>例えば要求を表すC++の構造体に<code>OVERLAPPED</code>、バッファ、オフセット、アプリ上の要求IDをまとめ、そのアドレスを対応表から引けるようにします。結果を待つワーカーが別にいる場合は、発行前に対応を登録し、発行側と回収側がともに参照を終えるまで要求を保持します。IOCPが返すポインターは、アプリが渡した領域を指します。構造体を途中で移動させると対応が崩れるため、例えば可変長配列に格納した要求を扱う場合は再確保に注意します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/minwinbase/ns-minwinbase-overlapped" target="_blank" rel="noreferrer">Microsoft: OVERLAPPED</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatus</a></p><h2 id="発行結果から、回収を待つ要求を決める" tabindex="-1">発行結果から、回収を待つ要求を決める <a class="header-anchor" href="#発行結果から、回収を待つ要求を決める" aria-label="Permalink to &quot;発行結果から、回収を待つ要求を決める&quot;">​</a></h2><p>完了通知を抑制する設定を使わず、関連付け済みの通常ファイルで<code>ReadFile</code>を呼んだ場合です。<code>FALSE</code>で戻ったら直後の<code>GetLastError()</code>で理由を調べます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">Microsoft: ReadFile</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-setfilecompletionnotificationmodes" target="_blank" rel="noreferrer">Microsoft: 完了通知モード</a></p><table tabindex="0"><thead><tr><th><code>ReadFile</code>の戻り方</th><th>発行側でわかること</th><th>この要求の回収</th></tr></thead><tbody><tr><td><code>TRUE</code></td><td>読み取りは呼出し中に成功した。</td><td><strong>即時成功でも完了パケットを回収する。</strong></td></tr><tr><td><code>FALSE</code>＋<code>ERROR_IO_PENDING</code></td><td>要求が受理され、未完了として返った。</td><td>完了パケットで最終結果を確認する。</td></tr><tr><td><code>FALSE</code>＋ほかのエラー</td><td>呼出し中にエラーが確定した。</td><td>発行側で結果を扱う。この要求のパケットは待たない。</td></tr></tbody></table><p>通常の設定では、<code>TRUE</code>と<code>ERROR_IO_PENDING</code>を同じ回収経路にまとめられます。<code>TRUE</code>の分もポート側で一度だけ処理し、ポートから受け取るまで<code>OVERLAPPED</code>を保持します。ファイル末尾を表す<code>ERROR_HANDLE_EOF</code>は、発行時に確定する場合と、発行後の結果として受け取る場合があります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/testing-for-the-end-of-a-file" target="_blank" rel="noreferrer">Microsoft: Testing for the End of a File</a> · <a href="https://devblogs.microsoft.com/oldnewthing/20190719-00/?p=102722" target="_blank" rel="noreferrer">Microsoft: 即時完了と通知モード</a> · <a href="https://devblogs.microsoft.com/oldnewthing/20211117-00/?p=105933" target="_blank" rel="noreferrer">Microsoft: 即時失敗と通知の関係</a></p><p>通知を変える仕組みは、適用範囲で区別します。</p><table tabindex="0"><thead><tr><th>設定</th><th>省略される通知</th></tr></thead><tbody><tr><td>ハンドルに<code>FILE_SKIP_COMPLETION_PORT_ON_SUCCESS</code>を設定</td><td>そのハンドルの要求が<strong>即時成功</strong>したときの完了パケット。pendingになった要求は完了時に回収する。</td></tr><tr><td>要求の<code>OVERLAPPED.hEvent</code>に、有効なイベントハンドルの最下位ビットを1にした値を指定</td><td>その要求の完了パケット。通常のイベントハンドルを設定するだけなら、この抑制条件には該当しない。</td></tr><tr><td>ハンドルに<code>FILE_SKIP_SET_EVENT_ON_HANDLE</code>を設定</td><td>条件を満たしたときにファイルオブジェクト自身のイベントをシグナル状態にする処理。完了ポートへのパケットや、要求に明示したイベントの通知はこのフラグの対象外。</td></tr></tbody></table><p>通知を省略する設定を使う経路では、即時成功を発行側で処理するなど、受理した要求をどこで終端として扱うかを設定と合わせます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-setfilecompletionnotificationmodes" target="_blank" rel="noreferrer">Microsoft: SetFileCompletionNotificationModes</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatus</a></p><h2 id="getqueuedcompletionstatusの戻り値を読む" tabindex="-1">GetQueuedCompletionStatusの戻り値を読む <a class="header-anchor" href="#getqueuedcompletionstatusの戻り値を読む" aria-label="Permalink to &quot;GetQueuedCompletionStatusの戻り値を読む&quot;">​</a></h2><p>ワーカーは<code>GetQueuedCompletionStatus</code>で一件を取り出します。I/O完了なら転送されたバイト数、完了キー、<code>OVERLAPPED*</code>が渡されます。<code>FALSE</code>のときは直後の<code>GetLastError()</code>を保存し、同時に<code>OVERLAPPED*</code>の出力を確認します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatus</a></p><table tabindex="0"><thead><tr><th>戻り値</th><th><code>OVERLAPPED*</code>の出力</th><th>読み方</th></tr></thead><tbody><tr><td><code>TRUE</code></td><td>非<code>nullptr</code>（OSによるI/O完了の場合）</td><td>成功したI/Oのパケットを回収した。実際の転送数を使う。</td></tr><tr><td><code>FALSE</code></td><td>非<code>nullptr</code></td><td>失敗したI/Oのパケットを回収した。その要求を終端として扱い、エラーコードを読む。</td></tr><tr><td><code>FALSE</code></td><td><code>nullptr</code></td><td>パケットを回収できなかった。例えば待機時間切れの<code>WAIT_TIMEOUT</code>。待機中にポートが閉じられた場合は<code>ERROR_ABANDONED_WAIT_0</code>。この行ではキーやバイト数の出力を使わない。</td></tr><tr><td><code>TRUE</code></td><td><code>nullptr</code>（手動通知をこの形式で送った場合）</td><td>アプリが投稿した制御用パケットを回収した。キーに従って処理する。</td></tr></tbody></table><p>例えば<code>FALSE</code>かつ非<code>nullptr</code>で<code>ERROR_OPERATION_ABORTED</code>なら、その要求のキャンセル完了を回収しました。一方、待機の時間切れは、その呼出しがパケットを取り出せず戻ったという結果です。発行済み要求は寿命を保ち、キャンセルを要求した場合も終端の通知まで追います。<a href="/study/os/cancelling-overlapped-io.html">非同期I/Oのキャンセルと終了処理</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex" target="_blank" rel="noreferrer">Microsoft: CancelIoEx</a></p><h3 id="アプリからワーカーを起こす" tabindex="-1">アプリからワーカーを起こす <a class="header-anchor" href="#アプリからワーカーを起こす" aria-label="Permalink to &quot;アプリからワーカーを起こす&quot;">​</a></h3><p><code>PostQueuedCompletionStatus(port, 0, stopKey, nullptr)</code>のように、アプリから制御用パケットを投稿できます。投稿した値はそのまま受け取れるため、I/Oには使わない<code>stopKey</code>を予約し、アプリの規約で判別します。例えば終了時は新規I/Oを止め、発行済み要求の完了を回収し終えてから、終了を待つ各ワーカーへ停止用のパケットを渡します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-postqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: PostQueuedCompletionStatus</a> · <a href="https://devblogs.microsoft.com/oldnewthing/?p=26693" target="_blank" rel="noreferrer">Microsoft: 手動投稿の値の扱い</a></p><h2 id="キューの順序とワーカーの並行度" tabindex="-1">キューの順序とワーカーの並行度 <a class="header-anchor" href="#キューの順序とワーカーの並行度" aria-label="Permalink to &quot;キューの順序とワーカーの並行度&quot;">​</a></h2><p>完了パケットは<strong>キューに入る順にFIFO</strong>で並びます。先に発行した読み取りが後から完了することもあり、複数のワーカーで扱うと、取り出しや後続処理の順序も変わり得ます。順序が必要なデータは要求IDやオフセットで並べ直します。Windowsの説明では、ポートで待つスレッドからは、最後に待機に入ったものを先に起こします（LIFO）。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/i-o-completion-ports" target="_blank" rel="noreferrer">Microsoft: I/O Completion Ports</a></p><p>作成時の<code>NumberOfConcurrentThreads</code>は、ポートに関連付く<strong>実行可能なワーカー数を制御する値</strong>です。<code>0</code>ならシステムのプロセッサー数が使われます。例えば並行度が1でも、アプリは複数のワーカーを作って待機させ、複数の読み取りを発行できます。先に動いていたワーカーが別の待ちに入ったとき、ポートは別のワーカーへ処理を渡せます。元のワーカーが再開した直後などは、一時的に指定値を超えることもあります。発行するI/Oの数やバッファの総量を抑える上限は、アプリ側で別に設けます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/i-o-completion-ports#threads-and-concurrency" target="_blank" rel="noreferrer">Microsoft: Threads and Concurrency</a> · <a href="/study/os/thread-scheduling.html">Windowsのスレッドスケジューリング</a></p><p>ゲームのローダーでは、I/Oの転送完了をきっかけに、展開やデコードの仕事を渡せます。転送、CPU処理、GPUへのアップロードを別の段階として計測すると、完了ポートの通知を受け取った時点から利用可能になるまでの遅れを追えます。<a href="/study/game/asset-loading.html">ゲームのアセット読み込み</a></p><h2 id="実践" tabindex="-1">実践 <a class="header-anchor" href="#実践" aria-label="Permalink to &quot;実践&quot;">​</a></h2><p>WindowsのC++サンプルでは、同じファイルに対する二つの読み取りを一つの完了ポートから回収します。両方に同じ完了キーが返り、異なる<code>OVERLAPPED*</code>で要求を識別できることを確認します。<a href="/study/practice/io/iocp-observation.html">C++でIOCPの完了通知を観察する</a></p>',29)])])}const m=o(d,[["render",n]]);export{u as __pageData,m as default};
